[
    DataContractAttribute, SysOperationAlwaysInitialize
]
public class METVendorRebateOffRemittanceCalcTaskContract extends METSysOperationTaskDataContract
{
    guid queueId;
    TransDate asOnDate;
    TransDate reversalDate;
    NoYes groupByDepartment;
