Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_queueId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _queueId = queueId)
{
    queueId = _queueId;
    return queueId;
}

[DataMember, SysOperationControlVisibility(false)]
public TransDate parmAsOnDate(TransDate _asOnDate = asOnDate)
{
    asOnDate = _asOnDate;

    return asOnDate;
}

[DataMember, SysOperationControlVisibility(false)]
public NoYes parmGroupByDepartment(NoYes _groupByDepartment = groupByDepartment)
{
    groupByDepartment = _groupByDepartment;

    return groupByDepartment;
}

[DataMember, SysOperationControlVisibility(false)]
public NoYes parmGroupByChargeCode(NoYes _groupByChargeCode = groupByChargeCode)
{
    groupByChargeCode = _groupByChargeCode;

    return groupByChargeCode;
}

[DataMember, SysOperationControlVisibility(false)]
public TransDate parmReversalDate(TransDate _reversalDate = reversalDate)
{
    reversalDate = _reversalDate;

    return reversalDate;
}
